from typing import List
from math import gcd
from collections import defaultdict


class Solution:
    def numberOfSubsequences(self, nums: List[int]) -> int:
        n = len(nums)
        ratios = defaultdict(int)
        total = 0
        for r in range(4, n - 2):
            q = r - 2
            for p in range(q - 1):
                d = gcd(nums[p], nums[q])
                ratios[(nums[p] // d, nums[q] // d)] += 1
            for s in range(r + 2, n):
                d = gcd(nums[s], nums[r])
                total += ratios.get((nums[s] // d, nums[r] // d), 0)
        return total % (10**9 + 7)

from typing import List
from math import gcd
from collections import defaultdict


class Solution:
    def numberOfSubsequences(self, nums: List[int]) -> int:
        n = len(nums)
        ratios = defaultdict(int)
        total = 0
        for r in range(4, n - 2):
            q = r - 2
            for p in range(q - 1):
                ratios[nums[p] * 1000 // nums[q]] += 1
            for s in range(r + 2, n):
                total += ratios.get(nums[s] * 1000 // nums[r], 0)
        return total

from typing import List
from math import gcd
from collections import defaultdict


class Solution:
    def numberOfSubsequences(self, nums: List[int]) -> int:
        n = len(nums)
        if len(set(nums)) == 1:
            from math import comb
            return comb(n - 4, 4)
        ratios = defaultdict(int)
        total = 0
        for r in range(4, n - 2):
            q = r - 2
            for p in range(q - 1):
                d = gcd(nums[p], nums[q])
                ratios[(nums[p] // d, nums[q] // d)] += 1
            for s in range(r + 2, n):
                d = gcd(nums[s], nums[r])
                total += ratios.get((nums[s] // d, nums[r] // d), 0)
        return total
